<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800&family=Space+Grotesk:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d42b1e;
    --blue: #0b3d91;
    --yellow: #f4c20d;
    --black: #111;
    --white: #f8f6f0;
    --grey: #c9c7c1;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    background: var(--white);
    color: var(--black);
    font-family: "Space Grotesk", sans-serif;
    line-height: 1.6;
  }
  .rule { border: none; border-top: 5px solid var(--black); }

  header {
    display: flex; justify-content: space-between; align-items: center;
    padding: 1rem 2rem; border-bottom: 4px solid var(--black);
    text-transform: uppercase; letter-spacing: .15em; font-size: .75rem; font-weight: 500;
  }
  header .dot { display: inline-block; width: .6em; height: .6em; background: var(--red); margin-right: .5em; }

  main { max-width: 1200px; margin: 0 auto; padding: 2rem; }

  .hero {
    display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; align-items: center;
    min-height: 78vh; padding: 2rem 0;
  }
  .composition {
    position: relative; aspect-ratio: 3 / 4; border: 6px solid var(--black);
    background: var(--white); overflow: hidden;
    box-shadow: 12px 12px 0 var(--black);
  }
  .composition .black { position: absolute; background: var(--black); }
  .c-v1 { top: 0; bottom: 0; left: 58%; width: 2.4%; }
  .c-v2 { top: 0; bottom: 0; left: 29%; width: 1.8%; }
  .c-h1 { top: 34%; left: 0; right: 0; height: 2.4%; }
  .c-h2 { top: 72%; left: 0; right: 0; height: 2.4%; }
  .cell { position: absolute; }
  .cell.red { left: 60.4%; top: 0; right: 0; height: 32.4%; background: var(--red); }
  .cell.blue { left: 0; top: 74.4%; width: 27.2%; bottom: 0; background: var(--blue); }
  .cell.yellow { left: 60.4%; top: 74.4%; right: 0; bottom: 0; background: var(--yellow); }
  .cell.grey { left: 0; top: 0; width: 27.2%; height: 32.4%; background: var(--grey); }
  .cell.white1 { left: 29%; top: 0; width: 29.4%; height: 32.4%; background: var(--white); }
  .cell.white2 { left: 0; top: 34%; width: 58%; height: 37.6%; background: var(--white); }
  .cell.white3 { left: 60.4%; top: 34%; right: 0; height: 37.6%; background: var(--white); }
  .cell.white4 { left: 29%; top: 74.4%; width: 29.4%; bottom: 0; background: var(--white); }

  .eyebrow { text-transform: uppercase; letter-spacing: .2em; font-size: .7rem; font-weight: 600; color: var(--blue); }
  h1 {
    font-family: "Archivo", sans-serif; font-weight: 800;
    font-size: clamp(2rem, 4.5vw, 3.4rem); line-height: 1.05; letter-spacing: -0.02em;
    margin: .6rem 0 1rem;
  }
  h1 .red { color: var(--red); }
  .lede { font-size: 1.15rem; max-width: 34rem; }
  .cta-row { display: flex; gap: 1rem; margin-top: 1.6rem; flex-wrap: wrap; }
  a.btn {
    display: inline-block; text-decoration: none; text-transform: uppercase; letter-spacing: .12em;
    font-size: .78rem; font-weight: 600; padding: .85rem 1.4rem; border: 3px solid var(--black);
  }
  a.btn.primary { background: var(--black); color: var(--white); }
  a.btn.primary:hover { background: var(--red); border-color: var(--red); }
  a.btn.secondary { background: var(--white); color: var(--black); }
  a.btn.secondary:hover { background: var(--yellow); }

